function xzTermText(list, detail) {
  var out = [];
  (list || []).forEach(function (x) {
    var raw = String(x === undefined || x === null ? '' : x).replace(/[\[\]【】\s]/g, '');
    if (!raw) return;
    var m = /^组合(\d{1,4})$/i.exec(raw) || /^combo(\d{1,4})$/i.exec(raw);
    if (!m) { out.push(raw); return; }
    var c = null;
    try { c = xzComboTermsById(Number(m[1])); } catch (eC) { c = null; }
    if (c && c.terms && c.terms.length) {
      c.terms.forEach(function (t) { if (t && out.indexOf(t) < 0) out.push(t); });
    }
  });
  return out.join('、');
}
function xzTypeOf(name, fbT, fbA) {
  var sk = (typeof XZ_SKILL_INFO !== 'undefined') ? xzSkillInfo(name) : null;
  if (sk && sk.type) return { t: sk.type, a: sk.atk || '单体' };
  var pos = xzPosOf(name);
  if (/架势式|身法式|保命翻盘|通用式/.test(pos)) return { t: '增益', a: '单体' };
  if (/领域/.test(pos)) return { t: '增益', a: '单体' };
  if (/本命杀招|起手式|连击式|终结式|绝式/.test(pos)) return { t: '进攻', a: /范围/.test(pos) ? '范围' : '单体' };
  if (/范围式/.test(pos)) return { t: '进攻', a: '范围' };
  if (/本命式/.test(pos)) return { t: '增益', a: '单体' };
  return { t: fbT || '进攻', a: fbA || '单体' };
}
