            rows.push(_row('种类', ent.kind + '（' + (_isHeart ? '被动' : '主动') + '）'));
            if (_rec.品质) rows.push(_row('品质', _rec.品质));
            if (_rec.目标) rows.push(_row('目标', _rec.目标));
            /* ★★★ v376：人设里的「消耗」已经撤掉（它由品质档推导），
               所以这里不能只读 `_rec.消耗` —— 那会恒为 null ⇒ 面板上「消耗」这一行整个消失，
               而战斗里明明在扣蓝。**写的和算的不是一个数**是本项目最贵的一类 bug。
               ⇒ 没写就按品质推（与 04 的 `xzSkillMpOf` 同一张表）。 */
            var _mpShow = Number(_rec.消耗);
