            '<div class="xz-modal-body" data-xz-ovl-body>', bodyHtml, '</div>',
            '<div class="xz-modal-foot">',
            '<button type="button" class="xz-modal-btn-close" data-xz-act="close-modal">✕ 阅毕收起</button>',
            '</div>',
            '</div>'
