        var str = show(at(p + '.四维.力量'), '5');
        var agi = show(at(p + '.四维.敏捷'), '5');
        var sta = show(at(p + '.四维.体质'), '5');
        var intl = show(at(p + '.四维.智力'), '5');

        /* ★ v77：删掉 `isHurt`（唯一来源是已废除的伤势状态，且它本身从未被使用）。 */

