        '沙洲': { base: '#d2a458', ink: '#a2763a', alt: '#eecd8e', kind: 'sand' },
        '幽篁域': { base: '#3c7a58', ink: '#245440', alt: '#549a6e', kind: 'forest' },
        '荒原域': { base: '#96703e', ink: '#74522c', alt: '#b78f57', kind: 'waste' },
        '熔岩域': { base: '#8c3f32', ink: '#5e241b', alt: '#c2683f', kind: 'lava' },
