            if (!d || !d.body) d = doc();
            var old = d.getElementById('xz-cem-toast');
            if (old) old.remove();
            var t = d.createElement('div');
            t.id = 'xz-cem-toast';
            t.textContent = msg;
            d.body.appendChild(t);
