        var _galHas = (_galCur && _q05g && typeof _q05g.xzCustomHas === 'function')
            ? !!_q05g.xzCustomHas(_galCur) : false;
        if (_galCur) {
            h += '<div class="gal-me">'
                + '<button type="button" class="gal-me-up" data-gal-up="' + esc(_galCur) + '">⬆ 上传「' + esc(_galCur) + '」的立绘</button>'
                + (_galHas ? '<button type="button" class="gal-me-rm" data-gal-rm="' + esc(_galCur) + '">↺ 还原默认</button>' : '')
                + (_galHas ? '<i class="gal-me-on">自定义中</i>' : '')
                + '</div>';
        }
        h += '<div class="gal-list">';
        list.forEach(function (it, i) {
            h += '<div class="gal-cell' + (i === idx ? ' on' : '') + '" data-gal="' + i + '">'
                + '<img src="' + esc(galImgOf(it.urls[0])) + '" alt="" loading="lazy" onerror="xzImgAlt(this)">'
                + (it.urls.length > 1 ? '<em>' + it.urls.length + '</em>' : '')
                + '<span>' + esc(it.name) + '</span>'
                + '</div>';
        });
        h += '</div>';
        /* ★ v493：整条提示删掉（用户 2026-10-31：「26 人 / 70 张　·　点人看大图，
           ‹ › 换同一人的多张，这句话删了，你当玩家傻逼是吗」）。
           ⚠ 连同前面那个「N 人 / M 张」计数一起删 —— 用户引用的是整句，
             保留半句就等于没删。缩略图右上角的角标 `<em>` 仍然显示每人几张，信息没丢。 */
        bd.innerHTML = h;

