    '--xz-ink-paper:#0b1e25;',
    '--xz-ink-fiber:rgba(230,189,118,0.022);',
    '--xz-ink-rule:rgba(230,189,118,0.48);',
    '--xz-ink-rule-2:rgba(230,189,118,0.20);',
    '--xz-ink-tick:rgba(230,189,118,0.42);',
    '--xz-ink-edge:rgba(0,0,0,0.28);}',
